"""Original master-bank data. Correct option is first. Work in progress."""

def parse(raw):
    result = []
    for line in raw.strip().splitlines():
        stem, a, b, c, d, explanation = line.split('|')
        result.append((stem, (a, b, c, d), explanation))
    return result

